async function lwDivergencias(sb,tipo){const fuera=new Map;if(!sb)return fuera;const{data:data,error:error}=await sb.from("documentos_desactualizados").select("id,numero,congelado,ficha,diferencias").eq("tipo",tipo);if(error||!data)return fuera;data.forEach((d=>{if(Array.isArray(d.diferencias)&&d.diferencias.length)fuera.set(d.id,d)}));return fuera}function lwEscDivergencia(v){return String(v==null?"":v).replace(/[&<>"']/g,(c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c])))}function lwTextoDivergencia(d){const e=lwEscDivergencia;const filas=(d.diferencias||[]).map((x=>"<li><b>"+e(x.campo)+"</b>: aquí «"+e(x.documento)+"», en la ficha «"+e(x.ficha)+"»</li>")).join("");return"<p>Este documento dice algo distinto de la ficha de <b>"+e(d.ficha||"su cliente")+"</b>:</p>"+'<ul style="margin:0 0 10px;padding-left:18px">'+filas+"</ul>"+(d.congelado?"<p>Está <b>cerrado</b> (firmado, enviado o anulado), así que no se toca: si el dato importa, "+"hay que <b>reemitirlo</b>.</p>":"<p>Todavía se puede corregir: al traer los datos de la ficha, el documento queda al día. "+"Revisa y guarda.</p>")}if(typeof module!=="undefined")module.exports={lwDivergencias:lwDivergencias,lwTextoDivergencia:lwTextoDivergencia};